             <div id="${id}-error" class="error-text" aria-live="polite">${errorText ? escapeHtml(errorText) : ""}</div>
           </div>
         `;
       };

       const App = () => {
         const { values, errors, submitted } = state;
         const errorSummary = submitted && Object.keys(errors).length
           ? "Please fix the highlighted fields before submitting."
           : "Fields marked with an asterisk are required.";

         return `
           <section class="page-shell" aria-labelledby="page-title">
             <div class="hero">
               <h1 id="page-title">Contact support</h1>
               <p>Send our team a message and we will get back to you as soon as possible.</p>
             </div>

             <div class="card">
               <form id="support-form" novalidate>
                 <div class="error-banner" role="status" aria-live="polite">${escapeHtml(errorSummary)}</div>
                 ${Field({
                   id: "fullName",
                   label: "Full name",
                   type: "text",
                   value: values.fullName,
                   required: true,
                   errorText: errors.fullName,
                   autocomplete: "name",
                 })}
                 ${Field({
                   id: "email",
                   label: "Email address",
                   type: "email",
                   value: values.email,
                   required: true,
                   errorText: errors.email,
                   autocomplete: "email",
                 })}
                 ${Field({
                   id: "phone",
                   label: "Phone number",
                   type: "tel",
                   value: values.phone,
                   required: false,
                   helperText: "Optional. Use (555) 123-4567, 555-123-4567, or 5551234567.",
                   errorText: errors.phone,
                   autocomplete: "tel",
                   inputMode: "tel",
                 })}
                 <button type="submit">Submit request</button>
               </form>
             </div>
           </section>
         `;
       };

       const root = document.querySelector("main");

       const render = () => {
         root.innerHTML = App();
         const form = document.getElementById("support-form");

         ["fullName", "email", "phone"].forEach((id) => {
           const input = document.getElementById(id);
           input.value = state.values[id];
           input.addEventListener("input", (event) => {
             state.values[id] = event.target.value;
             if (state.submitted) {
               state.errors = validate(state.values);
               render();
             }
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;
           state.errors = validate(state.values);

           if (Object.keys(state.errors).length) {
             render();
             const firstInvalid = document.querySelector('[aria-invalid="true"]');
             if (firstInvalid) {
               firstInvalid.focus();
             }
             return;
           }

           const banner = document.querySelector(".error-banner");
           banner.textContent = "Request ready to send.";
         });
       };

       render();
     </script>
   </body>
 </html>

